def predict(probe):
    # Rule: remove all whitespace characters, then reverse the string [E1-E12]
    # Whitespace includes space, \t, \n, \r, \f, \v, \u00a0, \u2003 [E4, E6, E10]
    def transform(s):
        return ''.join(ch for ch in s if not ch.isspace())[::-1]
    return {"outputs": [transform(x) for x in probe["inputs"]]}
